import {ContractError} from './cloud-contract.mjs';
import {attendanceId} from './attendance-contract.mjs';
import {validMonth} from './monthly-contract.mjs';
import {pagedRows} from './management-model.mjs';
export const payrollMoney=c=>new Intl.NumberFormat('zh-CN',{style:'currency',currency:'CNY'}).format(c/100);
export function payrollCents(v,signed=false){if(typeof v!=='string'||!(signed?/^-?\d{1,11}(?:\.\d{1,2})?$/:/^\d{1,11}(?:\.\d{1,2})?$/).test(v))throw new ContractError('金额最多两位小数，请直接填写数字。');const neg=v.startsWith('-'),[a,b='']=v.replace('-','').split('.'),n=(Number(a)*100+Number(b.padEnd(2,'0')))*(neg?-1:1);return cents(n,signed);}
const cents=(v,signed=false)=>{if(!Number.isSafeInteger(v)||v<(signed?-1e12:0)||v>1e12)throw new ContractError('请核对金额范围。');return v;};
export function salaryRecord(r){attendanceId(r?.id);attendanceId(r.member_id);validMonth(r.effective_month);if(!Number.isSafeInteger(r.revision)||r.revision<1||typeof r.note!=='string'||!Number.isFinite(Date.parse(r.created_at)))throw new ContractError();cents(r.amount_cents);return r;}
export function draftRecord(r){attendanceId(r?.id);attendanceId(r.member_id);attendanceId(r.closure_id);attendanceId(r.salary_id);validMonth(r.month);if(!Number.isSafeInteger(r.revision)||r.revision<1||typeof r.note!=='string'||!Number.isFinite(Date.parse(r.created_at)))throw new ContractError();for(const k of ['base_cents','bonus_cents','allowance_cents','total_cents'])cents(r[k]);cents(r.adjustment_cents,true);if(r.total_cents!==r.base_cents+r.bonus_cents+r.allowance_cents+r.adjustment_cents)throw new ContractError();return r;}
export function payrollState(v){validMonth(v?.month);if(!Array.isArray(v.roster)||![v.attendanceValid,v.salaryChanged,v.attendanceChanged].every(x=>typeof x==='boolean'))throw new ContractError();for(const m of v.roster){attendanceId(m.id);if(typeof m.name!=='string')throw new ContractError();}if(v.member!==null){attendanceId(v.member?.id);if(!v.roster.some(m=>m.id===v.member.id))throw new ContractError();}if(v.salary!==null){salaryRecord(v.salary);if(v.salary.member_id!==v.member?.id)throw new ContractError();}if(v.draft!==null){draftRecord(v.draft);if(v.draft.member_id!==v.member?.id||v.draft.month!==v.month)throw new ContractError();}if(v.attendanceValid&&(!v.closure||v.closure.action!=='lock'))throw new ContractError();return v;}
export function payrollHistory(v,salaries){pagedRows(v);if(v.limit!==50)throw new ContractError();v.rows.forEach(salaries?salaryRecord:draftRecord);return v;}
export function payrollPayload(v,salaries=false){const keys=salaries?['requestKey','memberId','effectiveMonth','amountCents','expectedLatestId','note']:['requestKey','memberId','month','expectedLatestId','salaryId','closureId','baseCents','bonusCents','allowanceCents','adjustmentCents','note','confirmReviewed'];if(!v||keys.some(k=>!Object.hasOwn(v,k))||Object.keys(v).some(k=>!keys.includes(k))||typeof v.note!=='string'||!v.note.trim()||v.note.length>2000)throw new ContractError('请填写完整金额与说明。');attendanceId(v.requestKey);attendanceId(v.memberId);if(v.expectedLatestId!==null)attendanceId(v.expectedLatestId);if(salaries){validMonth(v.effectiveMonth);cents(v.amountCents);}else{validMonth(v.month);attendanceId(v.salaryId);attendanceId(v.closureId);for(const k of ['baseCents','bonusCents','allowanceCents'])cents(v[k]);cents(v.adjustmentCents,true);cents(v.baseCents+v.bonusCents+v.allowanceCents+v.adjustmentCents);if(v.confirmReviewed!==true)throw new ContractError('请确认已核对本次金额及引用版本。');}return {...v,note:v.note.trim()};}
